/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Distorsion calculus */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Leading edge segment formated rib(i,97) extra */
/* end reformat */
    i__1 = nribss - 1;
    for (i__ = 0; i__ <= i__1; ++i__) {
	if (i__ < nribss) {
	    j = np[i__ + 101];
	    d__1 = u[i__ + (j + 4500) * 101 - 50601] - u[i__ + (j + 5000) * 
		    101 - 50601];
	    d__2 = v[i__ + (j + 4500) * 101 - 50601] - v[i__ + (j + 5000) * 
		    101 - 50601];
	    rib[i__ + 9696] = sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
/*       write (*,*) "rib(i,97) ",i,rib(i,97) */
	}
    }
