    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_wsfi(&io___836);
    do_fio(&c__1, (char *)&calage, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + (float)60.;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_copy(xtext, "center pressure= ", (ftnlen)50, (ftnlen)17);
    d__1 = x0 - xkf * 220;
    d__2 = y0 + 80;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_wsfi(&io___837);
    do_fio(&c__1, (char *)&cpress, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + 80;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_copy(xtext, "glide ratio= ", (ftnlen)50, (ftnlen)13);
    d__1 = x0 - xkf * 220;
    d__2 = y0 + 100;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_wsfi(&io___838);
    do_fio(&c__1, (char *)&planeig, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + 100;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_copy(xtext, "glide angle= ", (ftnlen)50, (ftnlen)13);
    d__1 = x0 - xkf * 220;
    d__2 = y0 + 120;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_wsfi(&io___839);
    do_fio(&c__1, (char *)&afinesse, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + 120;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_copy(xtext, "angle of attack= ", (ftnlen)50, (ftnlen)17);
    d__1 = x0 - xkf * 220;
    d__2 = y0 + 140;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_wsfi(&io___840);
    do_fio(&c__1, (char *)&aoa, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + 140;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
    s_copy(xtext, "assiette= ", (ftnlen)50, (ftnlen)10);
    d__1 = x0 - xkf * 220;
    d__2 = y0 + 160;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
