    do_fio(&c__1, (char *)&assiette, (ftnlen)sizeof(doublereal));
    e_wsfi();
    d__1 = x0 - xkf * 50;
    d__2 = y0 + 160;
    txt_(&d__1, &d__2, &c_b1964, &c_b1114, xtext, &c__7, (ftnlen)50);
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*     11. CALCULA LONGITUDS EXTRA INTRA EN PANELLS I PERFILS. MARKS */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*     WARNING: Additional vent marks in section 8.5 (!) */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*        write (*,*) "pi 11. =",pi */
/*      11.1 Extrados */
    i__1 = nribss;
    for (i__ = 1; i__ <= i__1; ++i__) {
	rib[i__ + 2929] = (float)0.;
/* extra panel left */
	rib[i__ + 3030] = (float)0.;
/* extra rib */
	rib[i__ + 3131] = (float)0.;
/* extra panel right */
	rib[i__ + 3232] = (float)0.;
/* intra panel left */
	rib[i__ + 3333] = (float)0.;
/* intra rib */
	rib[i__ + 3434] = (float)0.;
/*      Compute lengths extrados */
/* intra panel right */
	i__2 = np[i__ + 101] - 1;
	for (j = 1; j <= i__2; ++j) {
/*      WARNING longituds a dreta i esquerra de la costella extrados! */
/*      Arreglat amb el vector 29 definit mes enrera */
/*       rib(i,30)=rib(i,30)+sqrt((u(i-1,j,29)-u(i-1,j+1,29))**2.+ */
/*     + ((v(i-1,j,29)-v(i-1,j+1,29))**2.)) */
/*      ATENCIO, veure si compatible amb cas reformat especial */
	    d__1 = u[i__ - 1 + (j + 5000) * 101 - 50601] - u[i__ - 1 + (j + 
		    5001) * 101 - 50601];
	    d__2 = v[i__ - 1 + (j + 5000) * 101 - 50601] - v[i__ - 1 + (j + 
		    5001) * 101 - 50601];
	    rib[i__ + 2929] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	    d__1 = u[i__ + (j + 1500) * 101 - 50601] - u[i__ + (j + 1501) * 
		    101 - 50601];
	    d__2 = v[i__ + (j + 1500) * 101 - 50601] - v[i__ + (j + 1501) * 
		    101 - 50601];
	    rib[i__ + 3030] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	    d__1 = u[i__ + (j + 4500) * 101 - 50601] - u[i__ + (j + 4501) * 
		    101 - 50601];
	    d__2 = v[i__ + (j + 4500) * 101 - 50601] - v[i__ + (j + 4501) * 
		    101 - 50601];
	    rib[i__ + 3131] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	}
/*      Compute lengths intrados */
	i__2 = np[i__] - 1;
	for (j = np[i__ + 101] + np[i__ + 202]; j <= i__2; ++j) {
	    d__1 = u[i__ - 1 + (j + 5000) * 101 - 50601] - u[i__ - 1 + (j + 
		    5001) * 101 - 50601];
	    d__2 = v[i__ - 1 + (j + 5000) * 101 - 50601] - v[i__ - 1 + (j + 
		    5001) * 101 - 50601];
	    rib[i__ + 3232] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	    d__1 = u[i__ + (j + 1500) * 101 - 50601] - u[i__ + (j + 1501) * 
		    101 - 50601];
	    d__2 = v[i__ + (j + 1500) * 101 - 50601] - v[i__ + (j + 1501) * 
		    101 - 50601];
	    rib[i__ + 3333] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	    d__1 = u[i__ + (j + 4500) * 101 - 50601] - u[i__ + (j + 4501) * 
		    101 - 50601];
	    d__2 = v[i__ + (j + 4500) * 101 - 50601] - v[i__ + (j + 4501) * 
		    101 - 50601];
	    rib[i__ + 3434] += sqrt(pow_dd(&d__1, &c_b1223) + pow_dd(&d__2, &
		    c_b1223));
	}
/*      Amplification cofficients */
	rib[i__ + 3535] = rib[i__ + 2929] / rib[i__ + 3030];
	rib[i__ + 3636] = rib[i__ + 3131] / rib[i__ + 3030];
	rib[i__ + 3737] = rib[i__ + 3232] / rib[i__ + 3333];
	rib[i__ + 3838] = rib[i__ + 3434] / rib[i__ + 3333];
	rib[3535] = rib[3536];
	rib[3636] = rib[3536];
	rib[3737] = rib[3738];
	rib[3838] = rib[3738];
/*       write (*,*) "rib(i,36) ",i, rib(i,36), rib(i,30) */
    }
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*     AND COMPUTE AGAIN!!! "AMPLICATION" COEFFICIENTS */
/*     in new vectors rib(i,190) to rib(i,201) */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Initilize vectors */
