/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      ELLIPSE */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int ellipse_(doublereal *u0, doublereal *v0, doublereal *a, 
	doublereal *b, doublereal *tet0, integer *linecolor)
{
    /* Builtin functions */
    double atan(doublereal), cos(doublereal), sin(doublereal);

    /* Local variables */
    static integer ll;
    static doublereal pi, xe[500], ye[500], p1x, p1y, p2x, p2y, tet;
    extern /* Subroutine */ int line_(doublereal *, doublereal *, doublereal *
	    , doublereal *, integer *);

    pi = atan(1.) * 4.;
    for (ll = 1; ll <= 40; ++ll) {
	tet = pi * (float)2. * (((real) ll - (float)1.) / (float)39.);
/*      write (*,*) ll,float(ll),tet," ",pi,"---" */
	xe[ll - 1] = *u0 + *a * cos(tet) * cos(*tet0) - *b * sin(tet) * sin(*
		tet0);
	ye[ll - 1] = *v0 + *a * cos(tet) * sin(*tet0) + *b * sin(tet) * cos(*
		tet0);
    }
    for (ll = 1; ll <= 39; ++ll) {
	p1x = xe[ll - 1];
	p2x = xe[ll];
	p1y = ye[ll - 1];
	p2y = ye[ll];
	line_(&p1x, &p1y, &p2x, &p2y, linecolor);
/*       write (*,*) ll,tet*180./pi,xe(ll),ye(ll) */
    }
    return 0;
} /* ellipse_ */

