/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      SUBROUTINE LINEAL INTERPOLATION */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int interpola_(doublereal *x1, doublereal *y1, doublereal *
	x2, doublereal *y2, doublereal *x3, doublereal *y3)
{
    static doublereal xb, xm;

    xm = (*y2 - *y1) / (*x2 - *x1);
    xb = *y2 - xm * *x2;
    *y3 = xm * *x3 + xb;
    return 0;
} /* interpola_ */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
