/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      SUBROUTINE LINE OFFSET */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int loffset_(doublereal *uo, doublereal *vo, integer *npo, 
	doublereal *xo)
{
    /* System generated locals */
    integer i__1;

    /* Builtin functions */
    double atan(doublereal), sin(doublereal), cos(doublereal);

    /* Local variables */
    static integer j;
    static doublereal alpha, alpha1, alpha2;

    /* Parameter adjustments */
    vo -= 501;
    uo -= 501;

    /* Function Body */
    i__1 = *npo;
    for (j = 1; j <= i__1; ++j) {
/*      Angle alpha */
	if (j == 1) {
	    alpha = atan((vo[j + 501] - vo[j + 500]) / (uo[j + 501] - uo[j + 
		    500]));
	}
	if (j >= 2 && j < *npo) {
	    alpha1 = atan((vo[j + 501] - vo[j + 500]) / (uo[j + 501] - uo[j + 
		    500]));
	    alpha2 = atan((vo[j + 500] - vo[j + 499]) / (uo[j + 500] - uo[j + 
		    499]));
	    alpha = (alpha1 + alpha2) * (float).5;
	}
	if (j == *npo) {
	    alpha = atan((vo[j + 500] - vo[j + 498]) / (uo[j + 500] - uo[j + 
		    498]));
	}
/*      OFFSET OTION 1 IS OK */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Offset points */
	if (vo[j + 500] >= 0.) {
	    uo[j + 1000] = uo[j + 500] - *xo * .1 * sin(alpha);
	    vo[j + 1000] = vo[j + 500] + *xo * .1 * cos(alpha);
	}
	if (vo[j + 500] >= 0. && uo[j + 500] > uo[j + 499] && j > 1) {
	    uo[j + 1000] = uo[j + 500] + *xo * .1 * sin(alpha);
	    vo[j + 1000] = vo[j + 500] - *xo * .1 * cos(alpha);
	}
	if (vo[j + 500] < 0.) {
	    uo[j + 1000] = uo[j + 500] + *xo * .1 * sin(alpha);
	    vo[j + 1000] = vo[j + 500] - *xo * .1 * cos(alpha);
	}
	if (uo[j + 500] == 0.) {
	    uo[j + 1000] = uo[j + 500] - *xo * .1;
	    vo[j + 1000] = vo[j + 500];
	}
/*       OPTION 1 */
/*      OFFSET  OTION 2 IS IN TEST */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*       if(uo(j,1).gt.uo(j+1,1).or.uo(j,1).eq.0.0d0) then */
/*       uo(j,2)=uo(j,1)+xo*0.1d0*dsin(alpha) */
/*       vo(j,2)=vo(j,1)-xo*0.1d0*dcos(alpha) */
/*       end if */
/*       if(uo(j,1).lt.uo(j+1,1)) then */
/*       uo(j,2)=uo(j,1)-xo*0.1d0*dsin(alpha) */
/*       vo(j,2)=vo(j,1)+xo*0.1d0*dcos(alpha) */
/*       end if */
/*       if(uo(j,npo).lt.uo(npo-1,1)) then */
/*       uo(npo,2)=uo(npo,1)-xo*0.1d0*dsin(alpha) */
/*       vo(npo,2)=vo(npo,1)+xo*0.1d0*dcos(alpha) */
/*       end if */
/*      OPTION 2 TEST */
/*       if (j.eq.24) then */
/*       write (*,*) "SUP", j,uo(j,2),uo(j,1),vo(j,2),vo(j,1),alpha */
/*       end if */
    }
/* j */
    return 0;
} /* loffset_ */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      SUBROUTINE LINE OFFSET2 */
/*      Another version */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int loffset2_(doublereal *uo, doublereal *vo, integer *npo, 
	doublereal *xo)
{
    /* System generated locals */
    integer i__1;

    /* Builtin functions */
    double atan(doublereal), sin(doublereal), cos(doublereal);

    /* Local variables */
    static integer j;
    static real pi;
    static doublereal alpha, xsign;

    /* Parameter adjustments */
    vo -= 501;
    uo -= 501;

    /* Function Body */
    xsign = -1.;
    pi = atan(1.) * 4.;
    i__1 = *npo;
    for (j = 1; j <= i__1; ++j) {
/*      Angle alpha definition and corrections */
	if (j == 1) {
	    alpha = atan((vo[j + 501] - vo[j + 500]) / (uo[j + 501] - uo[j + 
		    500]));
	}
	if (j >= 2 && j < *npo) {
	    alpha = atan((vo[j + 501] - vo[j + 500]) / (uo[j + 501] - uo[j + 
		    500]));
	}
	if (j == *npo) {
	    alpha = atan((vo[j + 500] - vo[j + 499]) / (uo[j + 500] - uo[j + 
		    499]));
	}
/*      Correction when x increasing */
	if (uo[j + 501] >= uo[j + 500] && j < *npo) {
	    alpha -= pi;
	}
	if (uo[j + 500] >= uo[j + 499] && j == *npo) {
	    alpha -= pi;
	}
/*      Definition of displaced points */
	uo[j + 1000] = uo[j + 500] + *xo * xsign * .1 * sin(alpha);
	vo[j + 1000] = vo[j + 500] - *xo * xsign * .1 * cos(alpha);
/*       write (*,*) j," fi ",alpha,(uo(j+1,1)-uo(j,1))*1000., */
/*     + uo(j,2),vo(j,2) */
    }
    return 0;
} /* loffset2_ */

