/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      SUBROUTINE llarlr */
/*      Computes length at left and right of the partial rectagular */
/*      panel i formed by npo points */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int llarlr_(integer *i__, integer *i12, integer *i22, 
	integer *npo, doublereal *ufr, doublereal *vfr, doublereal *llarl, 
	doublereal *llarr)
{
    /* System generated locals */
    integer i__1;
    doublereal d__1, d__2;

    /* Builtin functions */
    double pow_dd(doublereal *, doublereal *), sqrt(doublereal);

    /* Local variables */
    static integer j;

/*      Set panel side lengths */
    /* Parameter adjustments */
    llarr -= 404;
    llarl -= 404;
    vfr -= 50601;
    ufr -= 50601;

    /* Function Body */
    llarl[*i__ + (*i12 + *i22 * 3) * 101] = 0.;
    llarr[*i__ + (*i12 + *i22 * 3) * 101] = 0.;
    i__1 = *npo - 1;
    for (j = 1; j <= i__1; ++j) {
	d__1 = ufr[*i__ + (j + 4501) * 101] - ufr[*i__ + (j + 4500) * 101];
	d__2 = vfr[*i__ + (j + 4501) * 101] - vfr[*i__ + (j + 4500) * 101];
	llarl[*i__ + (*i12 + *i22 * 3) * 101] += sqrt(pow_dd(&d__1, &c_b1223) 
		+ pow_dd(&d__2, &c_b1223));
	d__1 = ufr[*i__ + (j + 5001) * 101] - ufr[*i__ + (j + 5000) * 101];
	d__2 = vfr[*i__ + (j + 5001) * 101] - vfr[*i__ + (j + 5000) * 101];
	llarr[*i__ + (*i12 + *i22 * 3) * 101] += sqrt(pow_dd(&d__1, &c_b1223) 
		+ pow_dd(&d__2, &c_b1223));
    }
/*       write (*,*) i,i12,i22,npo,llarl(i,i12,i22),llarr(i,i12,i22) */
    return 0;
} /* llarlr_ */

