    distance1 = distance;
/*      Distance P9-P7 */
    distpr_(&pgx[4], &pgy[4], &pgx[3], &pgy[3], &pgx[9], &pgy[9], &distance);
    distance2 = distance;
/*      Definition of ellipse semiaxis */
    a = *param1 / (float)200. * sqrt((pgx[5] - pgx[6]) * (pgx[5] - pgx[6]) + (
	    pgy[5] - pgy[6]) * (pgy[5] - pgy[6]));
