	y2 = xp2 * sin(tetha) + yp2 * cos(tetha);
	d__1 = pgx[9] + x1;
	d__2 = pgy[9] + y1;
	d__3 = pgx[9] + x2;
	d__4 = pgy[9] + y2;
	line_(&d__1, &d__2, &d__3, &d__4, &c__3);
